// Wuthering Tools+ — the upgrade-cost table (data/materials.json, GENERATED by wuwa-tools/materials/materials_sync.mjs),
// loaded on first use so the /account chunk does not carry its 110 KB (12 KB gzipped). One request per page load.
import type { MaterialsData } from "./costToMax";

let pending: Promise<MaterialsData> | null = null;

export function loadMaterials(): Promise<MaterialsData> {
  pending ??= import("./data/materials.json").then((m) => (m.default ?? m) as unknown as MaterialsData);
  // a failed load is not kept: the next drawer opening tries again
  pending.catch(() => (pending = null));
  return pending;
}
